css:
.wotstreet-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e6edf3;
    background: radial-gradient(1200px 600px at 12% -5%, #1c2740 0%, #0b1020 55%, #070a16 100%);
    border-radius: 18px;
}

.wotstreet-container * {
    box-sizing: border-box;
}

.wotstreet-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #15233f 0%, #1d2c52 50%, #3a1d52 100%);
    color: #f2f6fb;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(124, 156, 255, 0.22);
    box-shadow: 0 14px 36px rgba(4, 8, 20, 0.55);
}

.wotstreet-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.wotstreet-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd166;
    background: rgba(255, 209, 102, 0.10);
    border: 1px solid rgba(255, 209, 102, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.wotstreet-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c6d2e6;
}

.wotstreet-brand-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.wotstreet-brand-cell {
    background: rgba(20, 30, 54, 0.72);
    border: 1px solid rgba(124, 156, 255, 0.16);
    border-radius: 13px;
    padding: 13px 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.wotstreet-brand-num {
    font-weight: 800;
    font-size: 1.18rem;
    color: #7fe7c4;
    font-variant-numeric: tabular-nums;
}

.wotstreet-brand-lbl {
    font-size: 0.76rem;
    color: #9fb0cb;
    line-height: 1.4;
}

.wotstreet-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebcd6;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.wotstreet-period-counter #currentDay,
.wotstreet-period-counter #maxPeriods {
    font-weight: 800;
    color: #58c8ff;
}

.wotstreet-round-name {
    background: rgba(88, 200, 255, 0.14);
    color: #8fdcff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.wotstreet-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff9e64;
    background: rgba(255, 158, 100, 0.12);
    border: 1px solid rgba(255, 158, 100, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.wotstreet-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.wotstreet-status-card {
    background: linear-gradient(160deg, rgba(22, 33, 58, 0.92) 0%, rgba(13, 20, 38, 0.92) 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(124, 156, 255, 0.16);
    border-top: 4px solid #58c8ff;
    box-shadow: 0 8px 22px rgba(4, 8, 20, 0.45);
}

.wotstreet-card-sentiment { border-top-color: #7fe7c4; }
.wotstreet-card-reach { border-top-color: #ff5d73; }
.wotstreet-card-conversion { border-top-color: #58c8ff; }
.wotstreet-card-roi { border-top-color: #ffd166; }

.wotstreet-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #9fb0cb;
}

.wotstreet-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.05;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.wotstreet-card-sentiment .wotstreet-value { color: #7fe7c4; }
.wotstreet-card-reach .wotstreet-value { color: #ff5d73; }
.wotstreet-card-conversion .wotstreet-value { color: #58c8ff; }
.wotstreet-card-roi .wotstreet-value { color: #ffd166; }

.wotstreet-sublabel {
    font-size: 0.75rem;
    color: #8c9db6;
    line-height: 1.35;
}

/* Sentiment state colouring */
.wotstreet-card-sentiment.wotstreet-good { border-top-color: #7fe7c4; }
.wotstreet-card-sentiment.wotstreet-good .wotstreet-value { color: #7fe7c4; }
.wotstreet-card-sentiment.wotstreet-bad { border-top-color: #ff5d73; }
.wotstreet-card-sentiment.wotstreet-bad .wotstreet-value { color: #ff5d73; }
/* ROI state colouring */
.wotstreet-card-roi.wotstreet-roi-bad { border-top-color: #ff5d73; }
.wotstreet-card-roi.wotstreet-roi-bad .wotstreet-value { color: #ff5d73; }
.wotstreet-card-roi.wotstreet-roi-good { border-top-color: #7fe7c4; }
.wotstreet-card-roi.wotstreet-roi-good .wotstreet-value { color: #7fe7c4; }
/* Conversion state colouring */
.wotstreet-card-conversion.wotstreet-conv-bad .wotstreet-value { color: #ff9e64; }
.wotstreet-card-conversion.wotstreet-conv-good .wotstreet-value { color: #7fe7c4; }

.wotstreet-threat-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(255, 93, 115, 0.08);
    border: 1px solid rgba(255, 93, 115, 0.30);
    color: #d6c0c8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.wotstreet-threat-bar #bleedDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #ff5d73;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.wotstreet-threat-bar.wotstreet-bleed-low {
    background: rgba(127, 231, 196, 0.08);
    border-color: rgba(127, 231, 196, 0.30);
}
.wotstreet-threat-bar.wotstreet-bleed-low #bleedDisplay { color: #7fe7c4; }
.wotstreet-threat-bar.wotstreet-bleed-mid #bleedDisplay { color: #ffd166; }

.wotstreet-briefing {
    display: flex;
    gap: 14px;
    background: rgba(20, 30, 54, 0.78);
    border-left: 5px solid #58c8ff;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid rgba(124, 156, 255, 0.14);
    border-left: 5px solid #58c8ff;
}

.wotstreet-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.wotstreet-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.wotstreet-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c6d2e6;
}

.wotstreet-briefing-text strong { color: #8fdcff; }
.wotstreet-briefing-text em { color: #ffd166; font-style: italic; }

.wotstreet-controls {
    background: rgba(15, 23, 42, 0.85);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(124, 156, 255, 0.14);
    box-shadow: 0 8px 22px rgba(4, 8, 20, 0.4);
}

.wotstreet-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid rgba(124, 156, 255, 0.18);
    padding-bottom: 8px;
}

.wotstreet-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d6e0f0;
    margin: 14px 0 6px;
}

.wotstreet-container select,
.wotstreet-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid rgba(124, 156, 255, 0.30);
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0e1730;
    color: #eaf1fb;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.wotstreet-container select:focus,
.wotstreet-container input[type="number"]:focus {
    outline: none;
    border-color: #58c8ff;
    box-shadow: 0 0 0 3px rgba(88, 200, 255, 0.20);
}

.wotstreet-container select option {
    background-color: #0e1730;
    color: #eaf1fb;
}

.wotstreet-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #58c8ff;
}

.wotstreet-range-readout {
    font-size: 0.9rem;
    font-weight: 700;
    color: #aebcd6;
    margin-top: 6px;
}

.wotstreet-range-readout span:nth-child(2) {
    color: #58c8ff;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.wotstreet-hint {
    font-size: 0.8rem;
    color: #8c9db6;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.wotstreet-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.wotstreet-container .btn-primary {
    background: linear-gradient(135deg, #2f6bff 0%, #58c8ff 100%);
    border: none;
    color: #06122b;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(47, 107, 255, 0.40);
}

.wotstreet-container .btn-primary:hover {
    filter: brightness(1.08);
}

.wotstreet-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid rgba(124, 156, 255, 0.34);
    color: #aebcd6;
    background: transparent;
}

.wotstreet-coach {
    background: linear-gradient(160deg, #0c1530 0%, #160c2c 100%);
    color: #d6e0f0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(255, 209, 102, 0.22);
    box-shadow: 0 8px 22px rgba(4, 8, 20, 0.45);
}

.wotstreet-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd166;
    margin-bottom: 8px;
}

.wotstreet-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.wotstreet-coach-body strong { color: #7fe7c4; }
.wotstreet-coach-body em { color: #ffd166; font-style: italic; }

.wotstreet-history,
.wotstreet-chart {
    background: rgba(15, 23, 42, 0.85);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(124, 156, 255, 0.14);
}

.wotstreet-history h3,
.wotstreet-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.wotstreet-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c6d2e6;
}

.wotstreet-container table#usfHistoryTable th {
    background: rgba(88, 200, 255, 0.10);
    color: #8fdcff;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(124, 156, 255, 0.22);
}

.wotstreet-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(124, 156, 255, 0.10);
    color: #c6d2e6;
}

.wotstreet-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(124, 156, 255, 0.05);
}

.wotstreet-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .wotstreet-container {
        padding: 14px;
    }
    .wotstreet-header h1 {
        font-size: 1.7rem;
    }
    .wotstreet-brand-strip {
        grid-template-columns: repeat(2, 1fr);
    }
    .wotstreet-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .wotstreet-value {
        font-size: 2rem;
    }
    .wotstreet-clock {
        margin-left: 0;
    }
    .wotstreet-period-counter {
        font-size: 0.88rem;
    }
    .wotstreet-threat-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .wotstreet-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================================
   Completion debrief (v1.1.0) — namespaced .wots-cm-*, append-only.
   Matches the sim's dark navy / teal / gold palette. Rendered by
   WordOnTheStreetAdapter.formatCompletionMessage().
   ============================================================================ */
.wots-cm {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6edf3;
    background: radial-gradient(900px 420px at 15% -10%, #1c2740 0%, #0b1020 60%, #070a16 100%);
    border: 1px solid rgba(124, 156, 255, 0.22);
    border-radius: 16px;
    padding: 22px 24px 24px;
    max-width: 720px;
    margin: 8px auto;
    box-shadow: 0 14px 36px rgba(4, 8, 20, 0.55);
}
.wots-cm-head {
    display: flex; align-items: center; justify-content: space-between;
    gap: 16px; flex-wrap: wrap;
    border-bottom: 1px solid rgba(124, 156, 255, 0.18);
    padding-bottom: 14px; margin-bottom: 16px;
}
.wots-cm-verdict {
    font-size: 1.5rem; font-weight: 800; letter-spacing: -0.3px; line-height: 1.15;
}
.wots-cm-good .wots-cm-verdict { color: #7fe7c4; }
.wots-cm-mid  .wots-cm-verdict { color: #ffd166; }
.wots-cm-bad  .wots-cm-verdict { color: #ff8a9b; }
.wots-cm-score { display: flex; align-items: baseline; gap: 6px; white-space: nowrap; }
.wots-cm-score-num { font-size: 2.1rem; font-weight: 800; color: #ffffff; }
.wots-cm-score-max { font-size: 1rem; color: #8c9db6; }
.wots-cm-grade {
    margin-left: 10px; font-size: 0.82rem; font-weight: 700;
    color: #cfe0ff; background: rgba(124, 156, 255, 0.14);
    border: 1px solid rgba(124, 156, 255, 0.28);
    padding: 3px 10px; border-radius: 999px;
}
.wots-cm-kpis {
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 14px;
}
.wots-cm-kpi {
    background: rgba(21, 35, 63, 0.6); border: 1px solid rgba(124, 156, 255, 0.16);
    border-radius: 12px; padding: 12px 10px; text-align: center;
}
.wots-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #ffffff; }
.wots-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.6px; color: #8c9db6; margin-top: 4px; }
.wots-cm-kpi.wots-cm-ok { border-color: rgba(127, 231, 196, 0.5); box-shadow: inset 0 0 0 1px rgba(127, 231, 196, 0.14); }
.wots-cm-kpi.wots-cm-no { border-color: rgba(255, 93, 115, 0.45); }
.wots-cm-rev { font-size: 0.95rem; color: #cbd6e8; margin-bottom: 16px; }
.wots-cm-rev strong { color: #7fe7c4; font-size: 1.05rem; }
.wots-cm-rev span { color: #8c9db6; font-size: 0.85rem; }
.wots-cm-gates-h, .wots-cm-insights-h {
    font-size: 0.74rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700;
    color: #ffd166; margin: 6px 0 8px;
}
.wots-cm-gates { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.wots-cm-chip {
    font-size: 0.8rem; font-weight: 600; padding: 5px 11px; border-radius: 999px;
    border: 1px solid transparent;
}
.wots-cm-chip-ok { color: #061a12; background: #7fe7c4; }
.wots-cm-chip-no { color: #ffd7dd; background: rgba(255, 93, 115, 0.16); border-color: rgba(255, 93, 115, 0.45); }
.wots-cm-insights { margin: 0; padding-left: 18px; }
.wots-cm-insights li { font-size: 0.92rem; line-height: 1.5; color: #d7e0ee; margin-bottom: 8px; }
@media (max-width: 560px) {
    .wots-cm-kpis { grid-template-columns: repeat(2, 1fr); }
    .wots-cm-head { flex-direction: column; align-items: flex-start; }
}

