(function() {
    'use strict';

    class WordOnTheStreetAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Word on the Street`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Tulsi Naturals, INR) ----
            this.BUDGET_LAKH = 165;          // ₹1.65 crore monthly digital budget = 165 lakh
            this.START_SENTIMENT = 12;       // net sentiment (+71 → +12)
            this.HEALTHY_SENTIMENT = 71;     // pre-crisis net sentiment
            this.START_REACH = 2.4;          // rumor reach in millions at 72h
            this.START_CONVERSION = 4.1;     // hero-SKU conversion % (was 6.8)
            this.PRE_CONVERSION = 6.8;       // pre-crisis conversion %
            this.HERO_MONTHLY_CR = 5.6;      // hero SKU bills ~₹5.6 crore/month
            this.BLEED_CR = 1.7;             // sustained 30% conversion loss ≈ ₹1.7 cr/month
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    sentiment: this.START_SENTIMENT,    // net sentiment on the hero-SKU page
                    reach: this.START_REACH,            // rumor reach (millions of impressions)
                    conversion: this.START_CONVERSION,  // hero-SKU listing conversion (%)
                    roi: 0,                             // campaign ROI (×) — 0 until budget is deployed
                    bleed: this.BLEED_CR,               // monthly revenue bleed (₹ crore)
                    spentLakh: 0,                       // budget deployed so far (₹ lakh)
                    revenueSavedCr: 0,                  // cumulative revenue saved vs. the do-nothing bleed (₹ crore)

                    // ---- Sticky run-defining penalty flags ----
                    astroturfed: false,        // manufactured/incentivized fake reviews → listing suspension
                    silenceRun: false,         // chose silence → rumor became the only story
                    paidBeforeRepair: false,   // poured paid spend into a distrusted listing
                    dismissedGenuine: false,   // labelled the whole wave a smear; alienated real advocates
                    legalism: false,           // legalistic denial that ignored worried customers
                    lateStart: false,          // intervened after the rumor calcified

                    reachWave2: false,         // a second wave / banner threat materialised
                    sentimentRepaired: false,  // sentiment back into healthy territory at least once

                    sentimentHistory: [this.START_SENTIMENT],
                    reachHistory: [this.START_REACH],
                    conversionHistory: [this.START_CONVERSION],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors so a blind
                // click-through does NOT auto-win: slow, dismiss-as-attack,
                // ignore the algorithm, silence/legalism, fake reviews, paid-first.
                state.decisions = {
                    nature: `attack`,
                    spread: `everywhere`,
                    algo: `rumoronly`,
                    speed: 96,
                    posture: `silence`,
                    wom: `fake`,
                    journalist: `ignore`,
                    line: `none`,
                    paid: 120,
                    advocate: 15,
                    community: 10,
                    pr: 15,
                    reserve: 5,
                    sequence: `now`,
                    week2: `deny`,
                    rebalance: `moreads`,
                    playbook: `none`,
                    pitch: `vanity`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const na = document.getElementById(`natureInput`);
                const sp = document.getElementById(`spreadInput`);
                const al = document.getElementById(`algoInput`);
                const speed = document.getElementById(`speedInput`);
                if (na) decisions.nature = na.value;
                if (sp) decisions.spread = sp.value;
                if (al) decisions.algo = al.value;
                if (speed) decisions.speed = parseInt(speed.value, 10);
                if (!Number.isFinite(decisions.speed) || decisions.speed < 12 || decisions.speed > 120) {
                    warn(`warn_speed_range`); return false;
                }
            } else if (round === 2) {
                const po = document.getElementById(`postureInput`);
                const wo = document.getElementById(`womInput`);
                const jo = document.getElementById(`journalistInput`);
                const li = document.getElementById(`lineInput`);
                if (po) decisions.posture = po.value;
                if (wo) decisions.wom = wo.value;
                if (jo) decisions.journalist = jo.value;
                if (li) decisions.line = li.value;
            } else if (round === 3) {
                const paid = document.getElementById(`paidInput`);
                const adv = document.getElementById(`advocateInput`);
                const com = document.getElementById(`communityInput`);
                const pr = document.getElementById(`prInput`);
                const res = document.getElementById(`reserveInput`);
                const seq = document.getElementById(`sequenceInput`);
                if (paid) decisions.paid = parseFloat(paid.value);
                if (adv) decisions.advocate = parseFloat(adv.value);
                if (com) decisions.community = parseFloat(com.value);
                if (pr) decisions.pr = parseFloat(pr.value);
                if (res) decisions.reserve = parseFloat(res.value);
                if (seq) decisions.sequence = seq.value;

                const parts = [decisions.paid, decisions.advocate, decisions.community, decisions.pr, decisions.reserve];
                for (let i = 0; i < parts.length; i++) {
                    if (!Number.isFinite(parts[i]) || parts[i] < 0) { warn(`warn_alloc_negative`); return false; }
                }
                const total = parts.reduce((a, b) => a + b, 0);
                if (Math.round(total) !== this.BUDGET_LAKH) { warn(`warn_alloc_total`); return false; }
            } else if (round === 4) {
                const w2 = document.getElementById(`week2Input`);
                const rb = document.getElementById(`rebalanceInput`);
                const pb = document.getElementById(`playbookInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (w2) decisions.week2 = w2.value;
                if (rb) decisions.rebalance = rb.value;
                if (pb) decisions.playbook = pb.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let sentimentDelta = 0;   // net-sentiment points
            let reachDelta = 0;       // millions of impressions (negative = contained)
            let convDelta = 0;        // conversion percentage points
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;
            let spentThisRoundLakh = 0;

            if (round === 1) {
                // ---- Diagnose: ambiguity, super-spreaders, the algorithm, and timing ----
                switch (d.nature) {
                    case `ambiguous`: sentimentDelta += 3; reachDelta -= 0.2; coachKey = `coach_r1_ambiguous`; break;
                    case `attack`: ds.dismissedGenuine = true; sentimentDelta -= 4; reachDelta += 0.3; coachKey = `coach_r1_attack`; break;
                    case `quality`: sentimentDelta -= 6; reachDelta += 0.4; coachKey = `coach_r1_quality`; break;
                }
                switch (d.spread) {
                    case `hubs`: reachDelta -= 0.4; coachKey = (d.nature === `ambiguous`) ? `coach_r1_sharp` : coachKey; break;
                    case `everywhere`: reachDelta += 0.4; if (coachKey === `coach_default`) coachKey = `coach_r1_everywhere`; break;
                    case `late`: reachDelta += 0.6; if (coachKey === `coach_default`) coachKey = `coach_r1_late`; break;
                }
                switch (d.algo) {
                    case `demotion`: convDelta += 0.2; break;
                    case `price`: convDelta -= 0.3; if (coachKey === `coach_default` || coachKey === `coach_r1_attack`) coachKey = `coach_r1_price`; break;
                    case `rumoronly`: convDelta -= 0.2; if (coachKey === `coach_default`) coachKey = `coach_r1_rumoronly`; break;
                }
                // Timing on the doubling curve. The rumor doubles ~every 24h; waiting feeds reach.
                const hours = d.speed;
                if (hours <= 36) { reachDelta -= 0.8; sentimentDelta += 1; }
                else if (hours <= 72) { reachDelta -= 0.2; }
                else { reachDelta += 0.8 + (hours - 72) / 60; ds.lateStart = true; if (coachKey === `coach_default`) coachKey = `coach_r1_slow`; }

                summaryKey = (d.nature === `ambiguous` && d.spread === `hubs` && d.algo === `demotion` && hours <= 72) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Plan: response posture, WOM amplification, journalist, the ethical line ----
                switch (d.posture) {
                    case `empathy`: sentimentDelta += 16; reachDelta -= 0.6; convDelta += 0.5; coachKey = `coach_r2_empathy`; break;
                    case `rebuttal`: sentimentDelta += 7; reachDelta -= 0.3; convDelta += 0.2; coachKey = `coach_r2_rebuttal`; break;
                    case `legal`: ds.legalism = true; sentimentDelta -= 8; reachDelta += 0.4; convDelta -= 0.2; coachKey = `coach_r2_legal`; break;
                    case `silence`: ds.silenceRun = true; sentimentDelta -= 10; reachDelta += 2.4; convDelta -= 0.6; coachKey = `coach_r2_silence`; break;
                }

                // WOM amplification — genuine helps, fake reviews detonate the moat (sticky).
                switch (d.wom) {
                    case `genuine`:
                        // Mobilizing genuine advocates only works if you didn't brand them all enemies.
                        if (ds.dismissedGenuine) { sentimentDelta += 4; coachKey = `coach_r2_genuine_blocked`; }
                        else { sentimentDelta += 12; convDelta += 0.4; reachDelta -= 0.3; if (d.posture === `empathy`) coachKey = `coach_r2_genuine`; }
                        break;
                    case `fake`:
                        ds.astroturfed = true;
                        sentimentDelta -= 14; reachDelta += 1.0; convDelta -= 1.0;
                        coachKey = `coach_r2_fake`;
                        break;
                    case `none`:
                        sentimentDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r2_womnone`;
                        break;
                }

                // Journalist within the 72h window.
                switch (d.journalist) {
                    case `brief`: sentimentDelta += 4; reachDelta -= 0.4; break;
                    case `spin`: sentimentDelta -= 4; reachDelta += 0.5; break;
                    case `ignore`: sentimentDelta -= 3; reachDelta += 0.6; ds.silenceRun = (d.posture === `silence`) ? true : ds.silenceRun; break;
                }

                // The pre-committed ethical line.
                switch (d.line) {
                    case `nofakes`: sentimentDelta += 3; break;
                    case `quietfakes`: ds.astroturfed = true; sentimentDelta -= 6; convDelta -= 0.6; if (coachKey !== `coach_r2_fake`) coachKey = `coach_r2_quietfakes`; break;
                    case `none`: sentimentDelta -= 1; break;
                }

                summaryKey = ds.astroturfed ? `sum_r2_astroturf` :
                             (d.posture === `silence` ? `sum_r2_silence` :
                             (d.posture === `legal` ? `sum_r2_legal` :
                             ((d.posture === `empathy` && d.wom === `genuine` && d.line === `nofakes`) ? `sum_r2_good` : `sum_r2_weak`)));
            } else if (round === 3) {
                // ---- Decide: allocate the ₹1.65 crore and sequence paid vs. repair ----
                spentThisRoundLakh = (d.paid || 0) + (d.advocate || 0) + (d.community || 0) + (d.pr || 0) + (d.reserve || 0);
                const paidShare = (d.paid || 0) / this.BUDGET_LAKH;
                const repairShare = ((d.advocate || 0) + (d.community || 0) + (d.pr || 0)) / this.BUDGET_LAKH;

                // Trust-repair lines move sentiment & conversion.
                sentimentDelta += repairShare * 22;
                convDelta += repairShare * 1.4;
                if ((d.community || 0) >= 15) { reachDelta -= 0.3; }   // rapid-response staffing contains spread
                if ((d.reserve || 0) >= 10) { reachDelta -= 0.2; }     // contingency to chase a second wave

                // Paid media: only converts well once the page is trusted AND you actually
                // funded the repair this month. "Full budget into paid" is the decision-tree #3
                // trap even if sentiment looks repaired — you can't have a believable page while
                // starving the levers that make it believable.
                const trusted = ds.sentiment >= 45 && !ds.astroturfed;
                const starvedRepair = repairShare < 0.25;          // <~41 lakh on advocates+community+PR
                const paidHeavy = paidShare > 0.5;
                if (paidHeavy && (!trusted || starvedRepair)) {
                    // Pouring budget into a still-distrusted (or under-repaired) listing.
                    ds.paidBeforeRepair = true;
                    convDelta -= 0.4; sentimentDelta -= 2;
                    coachKey = `coach_r3_paidearly`;
                } else if (paidShare > 0.35 && trusted && !starvedRepair) {
                    // Paid amplifying an already-repaired page converts.
                    convDelta += 0.6; reachDelta -= 0.2;
                    coachKey = `coach_r3_paidgood`;
                }

                // The sequencing question, explicit.
                switch (d.sequence) {
                    case `after`: if (coachKey === `coach_default`) coachKey = `coach_r3_after`; sentimentDelta += 2; break;
                    case `now`:
                        // Defending visibility "now" only escapes the trap with a modest paid tilt
                        // on an already-trusted, still-funded page.
                        if (!trusted || starvedRepair || paidHeavy) { ds.paidBeforeRepair = true; if (coachKey === `coach_default`) coachKey = `coach_r3_now`; }
                        break;
                    case `never`: reachDelta += 0.3; if (coachKey === `coach_default`) coachKey = `coach_r3_never`; break;
                }

                if (repairShare >= 0.4 && d.sequence === `after` && paidShare <= 0.45 && !ds.astroturfed) {
                    coachKey = `coach_r3_balanced`;
                    summaryKey = `sum_r3_good`;
                } else if (ds.paidBeforeRepair) {
                    summaryKey = `sum_r3_paidearly`;
                } else if (d.sequence === `never`) {
                    summaryKey = `sum_r3_never`;
                } else {
                    summaryKey = `sum_r3_weak`;
                }
            } else if (round === 4) {
                // ---- Recover: the week-2 complication, re-balance, playbook, the CEO pitch ----
                switch (d.week2) {
                    case `document`: sentimentDelta += 8; reachDelta -= 0.8; convDelta += 0.5; coachKey = `coach_r4_document`; break;
                    case `panic`: sentimentDelta -= 4; reachDelta += 0.6; ds.reachWave2 = true; coachKey = `coach_r4_panic`; break;
                    case `deny`: ds.dismissedGenuine = true; sentimentDelta -= 6; reachDelta += 1.2; ds.reachWave2 = true; coachKey = `coach_r4_deny`; break;
                }

                switch (d.rebalance) {
                    case `triggers`: sentimentDelta += 5; convDelta += 0.6; reachDelta -= 0.3; break;
                    case `moreads`:
                        if (ds.sentiment < 45 || ds.astroturfed) { ds.paidBeforeRepair = true; convDelta -= 0.4; coachKey = `coach_r4_moreads`; }
                        else { convDelta += 0.3; }
                        break;
                    case `freeze`: sentimentDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r4_freeze`; break;
                }

                switch (d.playbook) {
                    case `system`: sentimentDelta += 4; reachDelta -= 0.2; if (d.week2 === `document`) coachKey = `coach_r4_system`; break;
                    case `adsonly`: sentimentDelta -= 1; break;
                    case `none`: sentimentDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r4_noplaybook`; break;
                }

                switch (d.pitch) {
                    case `scorecard`: sentimentDelta += 3; coachKey = (d.week2 === `document` && d.rebalance === `triggers`) ? `coach_r4_scorecard` : coachKey; break;
                    case `vanity`: sentimentDelta -= 2; coachKey = `coach_r4_vanity`; break;
                    case `blame`: sentimentDelta -= 4; coachKey = `coach_r4_blame`; break;
                }

                if (d.conviction >= 60) { sentimentDelta += 2; }
                else if (d.conviction <= 25) { sentimentDelta -= 2; }

                summaryKey = (d.week2 === `document` && d.rebalance === `triggers` && d.playbook === `system` && d.pitch === `scorecard`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped) ----
            ds.sentiment = Math.max(-100, Math.min(100, Math.round(ds.sentiment + sentimentDelta)));
            ds.reach = Math.max(0.4, Math.round((ds.reach + reachDelta) * 10) / 10);
            ds.conversion = Math.max(0, Math.min(this.PRE_CONVERSION, Math.round((ds.conversion + convDelta) * 100) / 100));

            // ---- Sticky penalties bite the KPIs (run-defining, hard to wash out) ----
            if (ds.astroturfed) {
                // Fraud detection purged the reviews and suspended the listing 7 days.
                ds.sentiment = Math.min(ds.sentiment, 20);
                ds.conversion = Math.min(ds.conversion, 4.0);
                ds.reach = Math.max(ds.reach, this.START_REACH);
            }
            if (ds.silenceRun) {
                // By day six reach hit ~4.8M, the banner went up, conversion fell to ~3.2%.
                ds.reach = Math.max(ds.reach, 4.0);
                ds.sentiment = Math.min(ds.sentiment, 35);
                ds.conversion = Math.min(ds.conversion, 5.0);
            }
            if (ds.dismissedGenuine) {
                ds.sentiment = Math.min(ds.sentiment, 55);
            }
            if (ds.sentiment >= 55) ds.sentimentRepaired = true;

            // ---- Budget & revenue model ----
            ds.spentLakh = Math.round((ds.spentLakh + spentThisRoundLakh) * 10) / 10;

            // Conversion recovery vs. the crashed 4.1% drives revenue recovered on the hero SKU.
            // Each conversion point above 4.1% recovers a slice of the ₹5.6 cr/month billing.
            const convGain = Math.max(0, ds.conversion - this.START_CONVERSION); // pts above the crash floor
            const recoveryFraction = convGain / (this.PRE_CONVERSION - this.START_CONVERSION); // 0..1 of the lost band
            // Bleed shrinks as conversion recovers.
            ds.bleed = Math.round(this.BLEED_CR * (1 - Math.max(0, Math.min(1, recoveryFraction))) * 10) / 10;
            // Cumulative revenue saved per round vs. doing nothing (₹ crore, hero SKU).
            ds.revenueSavedCr = Math.round((ds.revenueSavedCr + this.BLEED_CR * Math.max(0, Math.min(1, recoveryFraction)) * 0.5) * 10) / 10;

            // ROI = revenue saved (₹ cr) / spend (₹ cr). Paid-before-repair and astroturf crush it.
            const spendCr = ds.spentLakh / 100;
            if (spendCr > 0) {
                let roi = ds.revenueSavedCr / spendCr;
                if (ds.paidBeforeRepair) roi = Math.min(roi, 0.6);  // decision-tree #3: 0.6× ceiling
                if (ds.astroturfed) roi = Math.min(roi, 0.3);       // moat burned
                ds.roi = Math.round(roi * 100) / 100;
            } else {
                ds.roi = 0;
            }

            ds.sentimentHistory.push(ds.sentiment);
            ds.reachHistory.push(ds.reach);
            ds.conversionHistory.push(ds.conversion);

            // ---- Persist the composite where the gradebook / AGS + history readers look ----
            // Framework contract (results_utils.php): express_resolveDomainScore reads
            // domainState.performance.overallScore first, then a top-level score; and
            // express_extractHistory reads history[].domainState.performance.overallScore.
            // addToHistory() deep-clones domainState into each period snapshot, so writing
            // it here lands the per-period score in the gradebook by construction.
            const composite = this._composite(ds);
            ds.performance = { overallScore: composite, grade: this._gradeLetter(composite) };
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                sentiment: ds.sentiment,
                sentimentDelta: Math.round(sentimentDelta),
                reach: ds.reach,
                conversion: ds.conversion,
                roi: ds.roi,
                bleed: ds.bleed,
                revenueSavedCr: ds.revenueSavedCr,
                score: composite,
                overallScore: composite,
                astroturfed: ds.astroturfed,
                silenceRun: ds.silenceRun,
                paidBeforeRepair: ds.paidBeforeRepair,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`sentimentDisplay`, `domainState.sentiment`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.wotstreet-card-sentiment`);
                if (card) {
                    card.classList.toggle(`wotstreet-good`, n >= 45);
                    card.classList.toggle(`wotstreet-bad`, n < 20);
                }
                return (n > 0 ? `+` : ``) + n;
            });

            uiManager.bind(`reachDisplay`, `domainState.reach`, (v) => self._fmtReach(Number(v)));

            uiManager.bind(`conversionDisplay`, `domainState.conversion`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.wotstreet-card-conversion`);
                if (card) {
                    card.classList.toggle(`wotstreet-conv-good`, n >= 6.0);
                    card.classList.toggle(`wotstreet-conv-bad`, n < 4.2);
                }
                return self._fmtPct(n);
            });

            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.wotstreet-card-roi`);
                if (n <= 0) { if (card) { card.classList.remove(`wotstreet-roi-good`, `wotstreet-roi-bad`); } return `—`; }
                if (card) {
                    card.classList.toggle(`wotstreet-roi-good`, n >= 1.5);
                    card.classList.toggle(`wotstreet-roi-bad`, n < 1.0);
                }
                return self._fmtRoi(n);
            });

            uiManager.bind(`bleedDisplay`, `domainState.bleed`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.wotstreet-threat-bar`);
                if (bar) {
                    bar.classList.toggle(`wotstreet-bleed-low`, n <= 0.4);
                    bar.classList.toggle(`wotstreet-bleed-mid`, n > 0.4 && n <= 1.0);
                }
                return `₹` + self._fmtNum(n) + ` ` + window.mySimulation.t(`unit_cr_mo`);
            });

            // R1 speed slider readout.
            const speed = document.getElementById(`speedInput`);
            const speedReadout = document.getElementById(`speedReadout`);
            if (speed && speedReadout) {
                speedReadout.textContent = speed.value;
                speed.addEventListener(`input`, function() { speedReadout.textContent = speed.value; });
            }

            // R3 allocation live total.
            const allocIds = [`paidInput`, `advocateInput`, `communityInput`, `prInput`, `reserveInput`];
            const allocReadout = document.getElementById(`allocatedReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach(function(id) {
                    const el = document.getElementById(id);
                    if (el) { const v = parseFloat(el.value); if (Number.isFinite(v)) total += v; }
                });
                if (allocReadout) {
                    allocReadout.textContent = Math.round(total);
                    allocReadout.style.color = (Math.round(total) === self.BUDGET_LAKH) ? `#7fe7c4` : `#ff5d73`;
                }
            };
            allocIds.forEach(function(id) {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _fmtNum(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }
        _fmtReach(v) {
            // millions of impressions, e.g. "2.4M".
            return this._fmtNum(v) + `M`;
        }
        _fmtPct(v) {
            return this._fmtNum(v) + `%`;
        }
        _fmtRoi(v) {
            return this._fmtNum(v) + `×`;
        }

        // Composite 0–100 across the four KPIs (reach inverted) + the sticky run-defining
        // caps — the VERBATIM v1.0.0 scoring, factored out so calculateResults() can persist
        // the same value every period that getPerformanceSummary() reports at completion.
        // Scoring is unchanged; this is a refactor, not a re-tune.
        _composite(ds) {
            const sentiment = Math.round(ds.sentiment);
            const reach = Math.round(ds.reach * 10) / 10;
            const conversion = Math.round(ds.conversion * 100) / 100;
            const roi = Math.round(ds.roi * 100) / 100;
            const sentimentScore = Math.max(0, Math.min(100, (sentiment + 20) / 91 * 100)); // -20..+71 → 0..100
            const reachScore = Math.max(0, Math.min(100, (5.0 - reach) / (5.0 - 1.0) * 100)); // lower reach = higher
            const convScore = Math.max(0, Math.min(100, (conversion - this.START_CONVERSION) / (this.PRE_CONVERSION - this.START_CONVERSION) * 100));
            const roiScore = Math.max(0, Math.min(100, roi / 2.5 * 100));
            let composite = Math.round(sentimentScore * 0.30 + convScore * 0.28 + reachScore * 0.22 + roiScore * 0.20);
            // Sticky run-defining flags cap the composite (run-defining, hard to wash out).
            if (ds.astroturfed) composite = Math.min(composite, 35);
            if (ds.silenceRun) composite = Math.min(composite, 45);
            if (ds.paidBeforeRepair) composite = Math.min(composite, 60);
            if (ds.dismissedGenuine) composite = Math.min(composite, 60);
            return composite;
        }

        // Letter grade surfaced to the gradebook / AGS via domainState.performance.grade
        // (express_extractMetrics reads it). Bands track the verdict tiers.
        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 70) return `B`;
            if (c >= 58) return `C`;
            if (c >= 45) return `D`;
            return `F`;
        }

        // Localize the internal (English) verdict tier id. The English id stays the stable
        // key the scoring logic keys on; the label is resolved for display only.
        _gradeLabel(id) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Crisis Lost':        `verdict_crisis_lost`,
                'Curve Bent':         `verdict_curve_bent`,
                'Moat Burned':        `verdict_moat_burned`,
                'Silence Calcified':  `verdict_silence_calcified`,
                'Paid the Wrong Page': `verdict_paid_wrong_page`,
                'Partial Recovery':   `verdict_partial_recovery`
            };
            return map[id] ? t(map[id]) : id;
        }

        getChartConfig() {
            // Guarded translator: localize chart chrome, but fall back to the English literals
            // if the framework isn't ready when the config is first built.
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, fallback) => (t ? t(k) : fallback);
            return {
                womChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_sentiment`, `Net sentiment (−100…+100)`),
                                data: [],
                                borderColor: `#7fe7c4`,
                                backgroundColor: `rgba(127,231,196,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#7fe7c4`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_conversion`, `Hero-SKU conversion (×10, %)`),
                                data: [],
                                borderColor: `#58c8ff`,
                                backgroundColor: `rgba(88,200,255,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#58c8ff`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_reach`, `Rumor reach (×10, millions)`),
                                data: [],
                                borderColor: `#ff5d73`,
                                backgroundColor: `rgba(255,93,115,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#ff5d73`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#aebcd6`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                min: -20, max: 100, position: `left`,
                                ticks: { color: `#8c9db6` }, grid: { color: `rgba(124,156,255,0.10)` },
                                title: { display: true, text: L(`chart_axis_index`, `index`), color: `#8c9db6` }
                            },
                            x: {
                                ticks: { color: `#8c9db6` }, grid: { color: `rgba(124,156,255,0.06)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#8c9db6` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.sentimentHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Conversion (%) ×10 and reach (M) ×10 share the sentiment axis.
            const convScaled = ds.conversionHistory.map((v) => Math.round(v * 10));
            const reachScaled = ds.reachHistory.map((v) => Math.round(v * 10));
            return {
                womChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.sentimentHistory.map((v) => Math.round(v)) },
                        { data: convScaled },
                        { data: reachScaled }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const sentiment = Math.round(ds.sentiment);
            const reach = Math.round(ds.reach * 10) / 10;
            const conversion = Math.round(ds.conversion * 100) / 100;
            const roi = Math.round(ds.roi * 100) / 100;
            const revenueSaved = Math.round(ds.revenueSavedCr * 10) / 10;

            // Recovery thresholds.
            const sentimentBack = sentiment >= 50;
            const reachContained = reach <= 3.0;
            const conversionBack = conversion >= 6.0;
            const roiPositive = roi >= 1.0;

            // Composite 0–100 across the four KPIs (reach inverted) + the sticky run-defining
            // caps. Shares the _composite(ds) helper that calculateResults() persists every
            // period, so the completion composite == the last period's persisted score by
            // construction. (Mislabeling genuine worried buyers as a coordinated smear — Common
            // Error #5, the diagnostic failure Sudhir's ambiguity research is most about — is one
            // of the run-defining caps: a later good round cannot wash it out into a clean rescue.)
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.astroturfed) pattern = `astroturf`;
            else if (ds.silenceRun) pattern = `silence`;
            else if (ds.paidBeforeRepair) pattern = `paidearly`;
            else if (ds.legalism) pattern = `legalism`;
            else if (ds.dismissedGenuine) pattern = `dismissed`;
            else if (sentimentBack && conversionBack && reachContained && roiPositive) pattern = `recovered`;

            let performance = `Crisis Lost`;
            if (!ds.astroturfed && !ds.silenceRun && !ds.paidBeforeRepair && !ds.dismissedGenuine &&
                sentimentBack && conversionBack && reachContained && roiPositive && composite >= 75) {
                performance = `Curve Bent`;
            } else if (ds.astroturfed) {
                performance = `Moat Burned`;
            } else if (ds.silenceRun) {
                performance = `Silence Calcified`;
            } else if (ds.paidBeforeRepair && conversion < 6.0) {
                performance = `Paid the Wrong Page`;
            } else if (composite >= 58) {
                performance = `Partial Recovery`;
            }

            const insights = [];
            if (pattern === `recovered`) insights.push(window.mySimulation.t(`insight_recovered`));
            else if (pattern === `astroturf`) insights.push(window.mySimulation.t(`insight_astroturf`));
            else if (pattern === `silence`) insights.push(window.mySimulation.t(`insight_silence`));
            else if (pattern === `paidearly`) insights.push(window.mySimulation.t(`insight_paidearly`));
            else if (pattern === `legalism`) insights.push(window.mySimulation.t(`insight_legalism`));
            else if (pattern === `dismissed`) insights.push(window.mySimulation.t(`insight_dismissed`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.dismissedGenuine && pattern !== `dismissed`) insights.push(window.mySimulation.t(`insight_dismissed`));
            if (!conversionBack) insights.push(window.mySimulation.t(`insight_conversion_low`));
            if (!reachContained) insights.push(window.mySimulation.t(`insight_reach_high`));
            if (sentimentBack && conversionBack && roi < 1.0) insights.push(window.mySimulation.t(`insight_roi_low`));
            if (sentimentBack && conversionBack && reachContained && roiPositive) insights.push(window.mySimulation.t(`insight_sequenced`));

            return {
                sentiment: sentiment,
                reach: reach,
                conversion: conversion,
                roi: roi,
                revenueSaved: revenueSaved,
                sentimentBack: sentimentBack,
                reachContained: reachContained,
                conversionBack: conversionBack,
                roiPositive: roiPositive,
                astroturfed: ds.astroturfed,
                silenceRun: ds.silenceRun,
                paidBeforeRepair: ds.paidBeforeRepair,
                pattern: pattern,
                composite: composite,
                grade: this._gradeLetter(composite),
                performance: this._gradeLabel(performance),
                performanceId: performance,
                insights: insights
            };
        }

        // Rich, localized crisis debrief. Without this override the framework falls through to
        // the base "You completed N periods." stub and discards the composite, verdict, KPIs and
        // insights this sim already computes. Self-contained, namespaced (.wots-cm-*) markup.
        formatCompletionMessage(summary) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const esc = (v) => String(v == null ? `` : v).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));

            const composite = Math.round(Number(s.composite) || 0);
            const grade = esc(s.grade || this._gradeLetter(composite));
            const verdict = esc(s.performance || ``);
            const id = s.performanceId || ``;
            const tone = (id === `Curve Bent`) ? `good` : (id === `Partial Recovery`) ? `mid` : `bad`;

            const sentiment = Math.round(Number(s.sentiment) || 0);
            const sentimentStr = (sentiment > 0 ? `+` : ``) + sentiment;
            const reachStr = this._fmtReach(Number(s.reach) || 0);
            const convStr = this._fmtPct(Number(s.conversion) || 0);
            const roiVal = Number(s.roi) || 0;
            const roiStr = roiVal > 0 ? this._fmtRoi(roiVal) : `—`;
            const revSaved = `₹` + this._fmtNum(Number(s.revenueSaved) || 0);

            const kpi = (label, value, ok) =>
                `<div class="wots-cm-kpi ${ok ? `wots-cm-ok` : `wots-cm-no`}"><div class="wots-cm-kpi-val">${value}</div><div class="wots-cm-kpi-lbl">${label}</div></div>`;
            const chip = (ok, label) =>
                `<span class="wots-cm-chip ${ok ? `wots-cm-chip-ok` : `wots-cm-chip-no`}">${ok ? `✓` : `✕`} ${label} · ${ok ? esc(t(`cm_met`)) : esc(t(`cm_missed`))}</span>`;

            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<ul class="wots-cm-insights">` + insights.map((x) => `<li>${esc(x)}</li>`).join(``) + `</ul>`
                : ``;

            return `
                <div class="wots-cm wots-cm-${tone}">
                    <div class="wots-cm-head">
                        <div class="wots-cm-verdict">${verdict}</div>
                        <div class="wots-cm-score"><span class="wots-cm-score-num">${composite}</span><span class="wots-cm-score-max">/100</span><span class="wots-cm-grade">${esc(t(`cm_grade`))} ${grade}</span></div>
                    </div>
                    <div class="wots-cm-kpis">
                        ${kpi(esc(t(`cm_kpi_sentiment`)), sentimentStr, !!s.sentimentBack)}
                        ${kpi(esc(t(`cm_kpi_reach`)), reachStr, !!s.reachContained)}
                        ${kpi(esc(t(`cm_kpi_conversion`)), convStr, !!s.conversionBack)}
                        ${kpi(esc(t(`cm_kpi_roi`)), roiStr, !!s.roiPositive)}
                    </div>
                    <div class="wots-cm-rev">${esc(t(`cm_revenue_saved`))}: <strong>${revSaved}</strong> <span>${esc(t(`cm_unit_cr`))}</span></div>
                    <div class="wots-cm-gates-h">${esc(t(`cm_gates_heading`))}</div>
                    <div class="wots-cm-gates">
                        ${chip(!!s.sentimentBack, esc(t(`cm_gate_sentiment`)))}
                        ${chip(!!s.reachContained, esc(t(`cm_gate_reach`)))}
                        ${chip(!!s.conversionBack, esc(t(`cm_gate_conversion`)))}
                        ${chip(!!s.roiPositive, esc(t(`cm_gate_roi`)))}
                    </div>
                    <div class="wots-cm-insights-h">${esc(t(`cm_insights_heading`))}</div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.astroturfed) return window.mySimulation.t(`hint_astroturf`);
            if (ds.silenceRun) return window.mySimulation.t(`hint_silence`);
            if (ds.paidBeforeRepair) return window.mySimulation.t(`hint_paidearly`);
            if (ds.reach >= 4.0) return window.mySimulation.t(`hint_reach`);
            if (ds.dismissedGenuine && state.currentPeriod >= 2) return window.mySimulation.t(`hint_dismissed`);
            if (ds.sentiment < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_sentiment`);
            if (ds.sentiment >= 50 && ds.conversion >= 6.0 && ds.reach <= 3.0) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.sentiment`, label: `Sentiment`, i18nKey: `col_sentiment`, formatter: (v) => (v > 0 ? `+` : ``) + Math.round(v) },
                { key: `results.reach`, label: `Reach`, i18nKey: `col_reach`, formatter: (v) => self._fmtReach(Number(v)) },
                { key: `results.conversion`, label: `Conv.`, i18nKey: `col_conversion`, formatter: (v) => self._fmtPct(Number(v)) },
                { key: `results.roi`, label: `ROI`, i18nKey: `col_roi`, formatter: (v) => (Number(v) > 0 ? self._fmtRoi(Number(v)) : `—`) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

